//! My Tasks holds what astrid-web's My Tasks holds — where the clients agree.
//!
//! `contracts/fixtures/my-tasks.json` is generated by running web's pure `lib/my-tasks-scope.ts`
//! (`myTasksShows`, as `hooks/useFilterState.ts` calls it for `"my-tasks"`) over a table of ten
//! tasks. Each case names a reader, the two filters My Tasks offers, one task, and whether web
//! shows it. Every case here runs through [`my_tasks::filter`].
//!
//! **Completion and due date are deliberately not varied** — `filters.json` covers those, and two
//! fixtures asserting the same window is two places to fix it. So each case is answered with
//! `filterCompletion: "all"` and `filterDueDate: "all"`, which is what makes the fixture's
//! completed rows (`assigned-to-me-completed`) visible, and what makes the clock irrelevant:
//! `the_clock_cannot_change_an_answer` holds that claim to its word rather than trusting it.
//!
//! Nothing is disputed. The cases were all **D25** — the reader signed out, the task with no
//! `assigneeId`, or a non-empty `filterAssignee` — until astrid-web adopted iOS's scope (AWTD-1583):
//! only what is assigned to the reader, the nested `assignee` standing in for a missing id, empty
//! signed out, `filterAssignee` not applied. Those cases are ordinary ones now.

mod common;

use std::collections::BTreeMap;

use astrid_rules::filters::my_tasks::{filter, Preferences};
use astrid_rules::model::{date, Task};
use chrono::{DateTime, FixedOffset, Utc};
use serde_json::Value;

const FIXTURE: &str = include_str!("../../../contracts/fixtures/my-tasks.json");

struct Fixture {
    raw: Value,
    tasks: BTreeMap<String, Task>,
}

fn utc() -> FixedOffset {
    FixedOffset::east_opt(0).expect("UTC")
}

/// The fixture pins no clock, because nothing it varies depends on one. Any instant will do.
fn now() -> DateTime<Utc> {
    date::parse("2026-10-17T12:00:00Z").expect("an instant")
}

fn load() -> Fixture {
    let raw: Value = serde_json::from_str(FIXTURE).expect("the fixture parses");
    let tasks = raw["tasks"]
        .as_array()
        .expect("a task table")
        .iter()
        .map(|t| {
            let task: Task = serde_json::from_value(t.clone()).expect("a task decodes");
            (task.id.clone(), task)
        })
        .collect();
    Fixture { raw, tasks }
}

/// Whether the core's My Tasks shows this case's task, in the fixture's terms.
///
/// The whole table goes in and the answer is membership, rather than passing the one task: that is
/// how the shell calls it, and it is the only way a rule that looked at a task's neighbours could
/// be caught.
fn answer(f: &Fixture, case: &Value, now: DateTime<Utc>) -> bool {
    let preferences = Preferences {
        filter_priority: serde_json::from_value(case["filterPriority"].clone())
            .expect("a priority list"),
        filter_assignee: serde_json::from_value(case["filterAssignee"].clone())
            .expect("an assignee list"),
        filter_due_date: "all".into(),
        filter_completion: "all".into(),
        ..Default::default()
    };
    let table: Vec<Task> = f.tasks.values().cloned().collect();
    let wanted = case["task"].as_str().expect("a task id");

    filter(&table, case["reader"].as_str(), &preferences, now, utc())
        .iter()
        .any(|task| task.id == wanted)
}

#[test]
fn awtd_1262_every_undisputed_case_answers_as_web_does() {
    let f = load();
    let cases = f.raw["cases"].as_array().expect("cases");
    assert!(
        cases.len() >= 18,
        "found only {} agreed cases; the fixture has shrunk",
        cases.len()
    );

    let failures: Vec<String> = cases
        .iter()
        .filter_map(|case| {
            let ours = answer(&f, case, now());
            (Value::Bool(ours) != case["shown"])
                .then(|| format!("{}: web {}, core {ours}", case["id"], case["shown"]))
        })
        .collect();
    common::no_failures("my-tasks.json", &failures);
}

/// Every case is answered with completion and due date neutralised, so the instant must not matter.
///
/// Said in the module note and asserted here, because it is the assumption that would quietly rot:
/// the day a `"all"` completion starts consulting the recently-completed window, the agreed cases
/// would begin to depend on when the suite ran.
#[test]
fn awtd_1262_the_clock_cannot_change_an_answer() {
    let f = load();
    let later = date::parse("2027-04-02T03:00:00Z").expect("an instant");
    for case in f.raw["cases"].as_array().expect("cases") {
        assert_eq!(
            answer(&f, case, now()),
            answer(&f, case, later),
            "{} answered differently at a different instant",
            case["id"]
        );
    }
}

#[test]
fn awtd_1262_each_disputed_entry_still_disagrees_with_web() {
    let f = load();
    let answered: Vec<common::Answered> = f.raw["disputed"]
        .as_array()
        .expect("disputed")
        .iter()
        .map(|case| common::Answered {
            entry: case["entry"].as_str().expect("an entry").to_string(),
            id: case["id"].as_str().expect("an id").to_string(),
            agrees_with_web: Value::Bool(answer(&f, case, now())) == case["shown"],
        })
        .collect();
    common::each_dispute_still_disagrees(
        "my-tasks.json",
        &common::declared(&f.raw["disputes"]),
        &answered,
    );
}
